-- REVIEW BEFORE RUNNING. Not executed by Claude. Run manually in the Supabase SQL editor.
--
-- Evaluation v2:
--   1. problem_reference_cards: one cached answer key per problem, generated by
--      the evaluator the first time a problem is graded.
--   2. evaluations.review_flags: reasons a mentor should look at an evaluation
--      (wrong problem, prompt injection, too-short transcript, ...).
--   3. complete_evaluation_job gains a defaulted p_review_flags parameter.
--
-- Safe order: run this file FIRST, then deploy the new code.
--   * The new function keeps working for the old code (the new parameter has a
--     default, so the old 9-argument call still resolves).
--   * New code calls it with p_review_flags.
-- If the new code is deployed before this file, evaluation jobs fail at the
-- completion step and retry; the reference-card cache is simply skipped.

-- 1) Reference cards. RLS on with no policies: service role only.
create table if not exists public.problem_reference_cards (
    problem_id uuid primary key references public.problems(id) on delete cascade,
    card jsonb not null,
    model_name text not null,
    created_at timestamptz not null default now()
);
alter table public.problem_reference_cards enable row level security;
revoke all on table public.problem_reference_cards from anon, authenticated;

-- 2) Review flags on evaluations (existing rows get an empty list).
alter table public.evaluations
    add column if not exists review_flags jsonb not null default '[]'::jsonb;

-- 3) Replace complete_evaluation_job. The old signature must be dropped:
--    leaving both would make 9-argument calls ambiguous.
drop function if exists public.complete_evaluation_job(
    uuid, text, text, text, jsonb, numeric, text, jsonb, jsonb
);

create or replace function public.complete_evaluation_job(
    p_job_id uuid,
    p_worker_id text,
    p_model_name text,
    p_rubric_version text,
    p_scores jsonb,
    p_overall_score numeric,
    p_feedback text,
    p_strengths jsonb,
    p_improvements jsonb,
    p_review_flags jsonb default '[]'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path to ''
as $function$
declare
    current_job record;
    new_evaluation_id uuid;
begin
    if p_job_id is null
       or NULLIF(TRIM(p_worker_id), '') is null
       or NULLIF(TRIM(p_model_name), '') is null
       or NULLIF(TRIM(p_rubric_version), '') is null
       or NULLIF(TRIM(p_feedback), '') is null
       or p_overall_score is null
       or p_overall_score < 0
       or p_overall_score > 10
       or jsonb_typeof(p_scores) is distinct from 'object'
       or jsonb_typeof(p_strengths) is distinct from 'array'
       or jsonb_typeof(p_improvements) is distinct from 'array'
       or jsonb_typeof(p_review_flags) is distinct from 'array'
    then
        raise exception 'Invalid evaluation data';
    end if;

    select *
    into current_job
    from public.evaluation_jobs
    where id = p_job_id
    for update;

    if not found
       or current_job.status <> 'processing'
       or current_job.locked_by is distinct from TRIM(p_worker_id)
    then
        raise exception 'Job not found or worker does not own this job';
    end if;

    if exists (
        select 1
        from public.evaluations
        where submission_id = current_job.submission_id
    ) then
        raise exception 'Successful evaluation already exists';
    end if;

    insert into public.evaluations (
        submission_id,
        provider,
        model_name,
        rubric_version,
        scores,
        overall_score,
        feedback,
        strengths,
        improvements,
        review_flags
    )
    values (
        current_job.submission_id,
        'groq',
        TRIM(p_model_name),
        TRIM(p_rubric_version),
        p_scores,
        p_overall_score,
        TRIM(p_feedback),
        p_strengths,
        p_improvements,
        p_review_flags
    )
    returning id into new_evaluation_id;

    update public.evaluation_jobs
    set
        status = 'completed',
        locked_at = null,
        locked_by = null,
        last_error = null,
        updated_at = now()
    where id = p_job_id;

    update public.submissions
    set
        status = 'evaluated',
        video_delete_after = now() + interval '30 days',
        updated_at = now()
    where id = current_job.submission_id;

    return jsonb_build_object(
        'success', true,
        'message', 'Evaluation completed successfully',
        'evaluation_id', new_evaluation_id
    );
end;
$function$;

revoke all on function public.complete_evaluation_job(
    uuid, text, text, text, jsonb, numeric, text, jsonb, jsonb, jsonb
) from public, anon, authenticated;
grant execute on function public.complete_evaluation_job(
    uuid, text, text, text, jsonb, numeric, text, jsonb, jsonb, jsonb
) to service_role;
